cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- Base premiums per item type (price list catalogue) ---
  it.todo("empty item list -> premium 5 G (processing fee only)");
  it.todo("sword (plain, newcomer 0 years, first quote) -> base premium 100 G");
  it.todo("amulet (plain) -> base premium 60 G");
  it.todo("staff (plain) -> base premium 80 G");
  it.todo("potion (plain) -> base premium 40 G");
  it.todo("rune (component) -> base premium 25 G");
  it.todo("moonstone (component) -> base premium 25 G");

  // --- Insurance values per item type (catalogue, observed via claim cap) ---
  it.todo("sword insurance value 1000 G -> cap 2000 G");
  it.todo("amulet insurance value 600 G -> cap 1200 G");
  it.todo("staff insurance value 800 G -> cap 1600 G");
  it.todo("potion insurance value 400 G -> cap 800 G");
  it.todo("rune insurance value 250 G -> cap 500 G");
  it.todo("moonstone insurance value 250 G -> cap 500 G");

  // --- Building block of 3 alike components ---
  it.todo("2 runes -> 50 G base premium (no block)");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block; block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium (no block for 7)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");

  // --- Item-specific premium modifiers ---
  it.todo("cursed sword adds 50 % of its base premium -> 50 G surcharge");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge -> 30 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -> both surcharges apply (50 G + 30 G)");

  // --- Policy-wide premium modifiers ---
  it.todo("customer with exactly 2 years -> 20 % loyalty discount applies");
  it.todo("customer with 1 year -> no loyalty discount");
  it.todo("first insurance adds 10 % initial assessment surcharge on policy base");
  it.todo("second quote in a scenario gets 15 % follow-up contract discount");
  it.todo("first quote in a scenario gets no follow-up contract discount");
  it.todo("processing fee 5 G is added at the very end of every premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> policy base 160 G, curse surcharge 50 G (item base only)");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> 198 G (rounded up, MHPCO's favor)");
  it.todo("payout yielding 350.5 G -> 350 G (rounded down, MHPCO's favor)");
  it.todo("intermediate amounts stay fractional; only the final amount is rounded");

  // --- Integration examples ---
  it.todo("newcomer with cursed steel sword enchantment 3 -> premium 165 G");
  it.todo("3-year customer's second quote, cursed sword enchantment 7 -> premium 160 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("steel sword enchantment 3, damage 500 G -> payout 400 G (deductible 100 G)");
  it.todo("rune (no enchantment, no material), damage 200 G -> payout 100 G");
  it.todo("damage below the deductible -> payout 0 G, not negative");

  // --- Claim: special clauses ---
  it.todo("enchantment 8 sword, damage 1000 G -> 50 % clause applies");
  it.todo("enchantment 7 sword, damage 1000 G -> no 50 % clause, payout 900 G");
  it.todo("dragon-material sword enchantment 5, damage 800 G -> payout 700 G (full reimbursement)");
  it.todo("dragon-material sword enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50 % then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damaging sword 500 G and amulet 300 G -> payout 600 G (deductible per item)");

  // --- Claim: multiple items of the same type ---
  it.todo("policy with two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries on a two-sword policy -> each entry gets its own deductible");
  it.todo("more damage entries of a type than insured items -> rejected: CLI exits non-zero, stderr message");

  // --- Claim: cap ---
  it.todo("policy with sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword with premium 165 G -> cap still 2000 G (unmodified insurance value)");
  it.todo("policy with sword + 3 runes (block) -> insurance sum 1750 G, cap 3500 G (block affects premium only)");
  it.todo("sword policy cap 2000 G, first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 G on the same policy -> payout 600 G, remainingCap 0 G");

  // --- Error cases (chosen reading: domain throws Error; CLI exits non-zero and writes stderr) ---
  it.todo("quote with unknown item type 'broomstick' -> CLI exits non-zero, stderr message, no stdout results");
  it.todo("claim for an amulet when only a sword is insured -> CLI exits non-zero with stderr message");
  it.todo("claim damage with unknown itemType -> CLI exits non-zero with stderr message");
  it.todo("claim damage with amount -200 -> CLI exits non-zero with stderr message");

  // --- CLI contract ---
  it.todo("CLI reads scenario JSON from stdin and writes {results:[...]} to stdout in step order");
  it.todo("CLI schema example: amulet quote then amulet claim of 200 G -> premium and payout/remainingCap");
  it.todo("claim result reports both payout and remainingCap fields");
});
