const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const SWORD_BASE_PREMIUM = 100;

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

function basePremiumOf(item: Item): number {
  return item.type === "sword" ? SWORD_BASE_PREMIUM : 0;
}

function premiumFor(step: QuoteStep): number {
  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  return policyBase + firstInsurance + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map((step) => ({ premium: premiumFor(step) })) };
}
EOF
